-- Add detailed program information
CREATE TABLE IF NOT EXISTS university_programs (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  university_id INTEGER REFERENCES universities(id),
  faculty TEXT NOT NULL,
  department TEXT NOT NULL,
  program_name TEXT NOT NULL,
  degree_type TEXT CHECK (degree_type IN ('BSc', 'BA', 'BEng', 'BTech', 'LLB', 'MBBS', 'MSc', 'MA', 'MEng', 'PhD', 'PGD')),
  duration TEXT,
  requirements TEXT,
  career_prospects TEXT,
  accreditation TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Add facilities information
CREATE TABLE IF NOT EXISTS university_facilities (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  university_id INTEGER REFERENCES universities(id),
  facility_name TEXT NOT NULL,
  facility_type TEXT CHECK (facility_type IN ('academic', 'residential', 'sports', 'medical', 'library', 'laboratory', 'recreational', 'administrative')),
  description TEXT,
  capacity INTEGER,
  features TEXT[],
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Add admission information
CREATE TABLE IF NOT EXISTS university_admissions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  university_id INTEGER REFERENCES universities(id),
  admission_type TEXT CHECK (admission_type IN ('UTME', 'Direct Entry', 'Postgraduate', 'International')),
  requirements TEXT NOT NULL,
  cutoff_mark INTEGER,
  application_process TEXT,
  deadlines TEXT,
  fees_range TEXT,
  scholarships TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

