-- Enable RLS
ALTER TABLE university_programs ENABLE ROW LEVEL SECURITY;
ALTER TABLE university_facilities ENABLE ROW LEVEL SECURITY;
ALTER TABLE university_admissions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public can read programs" ON university_programs FOR SELECT USING (true);
CREATE POLICY "Public can read facilities" ON university_facilities FOR SELECT USING (true);
CREATE POLICY "Public can read admissions" ON university_admissions FOR SELECT USING (true);

CREATE POLICY "Authenticated can manage programs" ON university_programs FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Authenticated can manage facilities" ON university_facilities FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Authenticated can manage admissions" ON university_admissions FOR ALL USING (auth.role() = 'authenticated');
